mapper.select:
SELECT wcs.main_id as id, wcd.sku_id, wcd.sku_no, wcd.fn_sku, SUM(wcd.pack_qty) AS packQty, SUM(wcs.box_qty) AS boxQty FROM wms_carton_spec wcs LEFT JOIN wms_carton wc ON wc.spec_id = wcs.id and wcs.is_deleted = FALSE LEFT JOIN wms_carton_detail wcd ON wc.id = wcd.main_id AND wcd.is_deleted = FALSE WHERE wcs.is_deleted = FALSE AND wcd.sku_id is not null
AND wcs.main_id = #{mainId}
AND wcs.box_spec_no = #{boxSpecNo}
GROUP BY wcs.main_id, wcd.sku_id, wcd.sku_no, wcd.fn_sku

SELECT wcs.id, wcs.main_id as taskId, wcd.sku_id, wcd.sku_no, SUM(wcd.pack_qty) AS packQty, SUM(wcd.gross_weight) AS grossWeight, SUM(wcs.box_qty) AS boxQty, wcs.box_spec_no, wc.box_no FROM wms_carton_spec wcs LEFT JOIN wms_carton wc ON wc.spec_id = wcs.id and wcs.is_deleted = FALSE LEFT JOIN wms_carton_detail wcd ON wc.id = wcd.main_id AND wcd.is_deleted = FALSE WHERE wcs.is_deleted = FALSE AND wcd.sku_id is not null
AND wcs.main_id = #{mainId}
GROUP BY wcs.id, wcs.main_id, wcd.sku_id, wcd.sku_no, wcs.box_spec_no, wc.box_no
